#[cfg(test)]mod queue_tree_curve_tests {
 use super::*;use zopro_bn254::Fr;
 use ark_ec::{AffineRepr,CurveGroup,PrimeGroup};use ark_ff::{AdditiveGroup,PrimeField};
 fn ar(s:Fr)->ark_bn254::Fr{ark_bn254::Fr::from_bigint(ark_ff::BigInt(s.to_canonical())).unwrap()}
 fn equal(p:G2Affine,q:ark_bn254::G2Affine){if q.is_zero(){assert!(p.is_identity());return;}assert!(!p.is_identity());for(a,b)in[(p.x.c0,q.x.c0),(p.x.c1,q.x.c1),(p.y.c0,q.y.c0),(p.y.c1,q.y.c1)]{assert_eq!(a.to_canonical(),b.into_bigint().0);}}
 fn random(seed:&mut u64)->Fr{let mut bytes=[0;32];for b in bytes.chunks_exact_mut(8){*seed^=*seed<<13;*seed^=*seed>>7;*seed^=*seed<<17;b.copy_from_slice(&seed.to_le_bytes());}Fr::from_le_bytes_mod_order(&bytes)}
 fn fixture()->(Vec<Fr>,Vec<Fr>,Vec<G2Affine>,Vec<G2Affine>){let mut seed=0x18a76a490f21b2;let a=(0..199).map(|i|match i%11{0=>Fr::ZERO,1..=3=>Fr::ONE,4..=6=>-Fr::ONE,_=>random(&mut seed)}).collect::<Vec<_>>();let mut b=(0..199).map(|i|match i%9{0=>Fr::ZERO,1..=3=>Fr::ONE,4..=6=>-Fr::ONE,_=>random(&mut seed)}).collect::<Vec<_>>();b[198]=Fr::from(9176123u64);let g=G2Projective::generator();let points=G2Projective::batch_to_affine(&a.iter().map(|&s|g*s).collect::<Vec<_>>());let incoming=G2Projective::batch_to_affine(&b.iter().map(|&s|g*s).collect::<Vec<_>>());(a,b,points,incoming)}
 fn expected(a:&[Fr],b:&[Fr],n:usize,bins:usize,salt:usize)->Vec<ark_bn254::G2Affine>{let mut sums=a.iter().copied().map(ar).collect::<Vec<_>>();for x in sums.iter_mut().take(bins.min(4)){*x+=ar(b[198]);}for i in 0..n{let j=(i*37+i/7)%bins;let t=ar(b[i]);sums[j]+=if (i+salt)%3==0{-t}else{t};}sums.into_iter().map(|s|(ark_bn254::G2Projective::generator()*s).into_affine()).collect()}
 fn run(initial:&[G2Affine],incoming:&[G2Affine],n:usize,bins:usize,salt:usize,expected:&[ark_bn254::G2Affine]){
  let mut state=Window::new(R,200,BatchAdd::<G2Config>::default());state.affine[..initial.len()].copy_from_slice(initial);
  for j in 0..bins.min(4){state.add(j as u32,&incoming[198]);}
  for i in 0..n{let j=(i*37+i/7)%bins;state.queue.push((j as u32|if(i+salt)%3==0{1<<31}else{0},&incoming[i]));}
  state.ring_complete();assert!(state.batch.is_empty()&&state.queue.is_empty());assert!(state.busy.iter().all(|&n|n==0));let out=state.finish();
  for(&p,&q)in out.iter().zip(expected){equal(p,q);}assert!(out[initial.len()..].iter().all(G2Affine::is_identity));
 }
 #[test]fn independent_arkworks_roots_pending_and_exceptions(){let(a,b,p,q)=fixture();let saved=(p.clone(),q.clone());let mut cases=0;for bins in[1usize,2,7,32,199]{for n in[0,1,7,8,9,31,32,33,198,199]{for salt in 0..3{let expected=expected(&a,&b,n,bins,salt);run(&p,&q,n,bins,salt,&expected);cases+=1;}}}assert_eq!(cases,150);assert_eq!((p,q),saved);println!("QUEUE_TREE_ARKWORKS_CASES={cases}; outputs=29850; pending/signs/identities/doubling/opposites/cancellations/0..199 boundaries; inputs unchanged");}
 #[test]fn every_worker_and_concurrent_shared_pool(){let(a,b,p,q)=fixture();let saved=(p.clone(),q.clone());let oracle=expected(&a,&b,199,32,1);let mut visits=0;for workers in[1,4,16,32]{let pool=rayon::ThreadPoolBuilder::new().num_threads(workers).stack_size(512*1024).build().unwrap();let indexes=pool.broadcast(|ctx|{run(&p,&q,199,32,1,&oracle);ctx.index()});assert_eq!(indexes.len(),workers);let mut sorted=indexes;sorted.sort_unstable();assert_eq!(sorted,(0..workers).collect::<Vec<_>>());visits+=workers;}let pool=rayon::ThreadPoolBuilder::new().num_threads(8).stack_size(512*1024).build().unwrap();std::thread::scope(|scope|{let mut handles=vec![];for _ in 0..4{let(pool,p,q,oracle)=(&pool,&p,&q,&oracle);handles.push(scope.spawn(move||{for _ in 0..3{pool.install(||run(p,q,199,32,1,oracle));}}));}for h in handles{h.join().unwrap();}});assert_eq!((p,q),saved);assert_eq!(visits,53);println!("QUEUE_TREE_WORKER_VISITS={visits}; concurrent_calls=12; requested_stack_bytes=524288");}
}
